export const SpatialPower: React.FC = () => {
  // --- Parameters ---
  const [platform, setPlatform] = useState<SpatialPlatform>(SpatialPlatform.XENIUM);
  const [numPatients, setNumPatients] = useState(24);
  const [slicesPerPatient, setSlicesPerPatient] = useState(2);
  const [treatmentEffect, setTreatmentEffect] = useState(0.4); // Spatial co-localization change
  const [patientVariance, setPatientVariance] = useState(0.6); // Inter-patient ICC
  const [sliceVariance, setSliceVariance] = useState(0.2); // Intra-patient slice ICC

  const currentPlatform = PLATFORMS[platform];

  // --- Logic (PoweREST inspired hierarchical power) ---
  const calculationResults = useMemo(() => {
    const alpha = 0.05;
    const powerTarget = 0.8;

    // Total Variance = Patient + Slice + Technical
    // Hierarchical variance decomposition: Var_total = sigma_p^2 + sigma_s^2 + sigma_t^2
    const sigmaP2 = Math.pow(patientVariance, 2);
    const sigmaS2 = Math.pow(sliceVariance, 2);
    const sigmaT2 = currentPlatform.technicalVariance / currentPlatform.captureEfficiency;

    const calculateForN = (N: number, S: number) => {
      const se = Math.sqrt((sigmaP2 / N) + (sigmaS2 / (N * S)) + (sigmaT2 / (N * S * 500))); // assuming 500 ROIs/spots
      const z = (treatmentEffect / se) - getZScore(1 - alpha/2);
      return Math.max(0, Math.min(1, getNormalProbability(z)));
    };

    const powerCurve = [];
    for (let n = 4; n <= 80; n += 4) {
      powerCurve.push({
        n,
        power: calculateForN(n, slicesPerPatient) * 100,
        cost: n * slicesPerPatient * currentPlatform.costPerSlice / 1000 // in k$
      });
    }

    const currentPower = calculateForN(numPatients, slicesPerPatient);

    // Variance Breakdown for Bar Chart
    const varData = [
      { name: 'Patient', value: sigmaP2, fill: '#6366f1' },
      { name: 'Slice', value: sigmaS2, fill: '#ec4899' },
      { name: 'Technical', value: sigmaT2 / 500, fill: '#94a3b8' }
    ];

    return { powerCurve, currentPower, varData };
  }, [platform, numPatients, slicesPerPatient, treatmentEffect, patientVariance, sliceVariance]);

  // --- Visuals: Mock Tissue Canvas ---
  const tissueDots = useMemo(() => {
    const dots = [];
    const density = 20;
    for (let i = 0; i < 200; i++) {
      const x = Math.random() * 100;
      const y = Math.random() * 100;
      // Simulate tumor/stroma interface
      const isTumor = x < 60;
      const isInfiltrated = isTumor && (Math.random() < treatmentEffect * (x/60));
