      const se = Math.sqrt((sigmaP2 / N) + (sigmaS2 / (N * S)) + (sigmaT2 / (N * S * 500))); // assuming 500 ROIs/spots
      const z = (treatmentEffect / se) - getZScore(1 - alpha/2);
      return Math.max(0, Math.min(1, getNormalProbability(z)));
    };

