  const [treatmentEffect, setTreatmentEffect] = useState(0.4); // Spatial co-localization change
  const [patientVariance, setPatientVariance] = useState(0.6); // Inter-patient ICC
  const [sliceVariance, setSliceVariance] = useState(0.2); // Intra-patient slice ICC
