  VISIUM = '10x Visium (Spot-based)',
  XENIUM = '10x Xenium (Cell-based)',
  COSMX = 'NanoString CosMx (Cell-based)',
  SLIDE_SEQ = 'Slide-seq (Bead-based)'
}

