  const [numPatients, setNumPatients] = useState(24);
  const [slicesPerPatient, setSlicesPerPatient] = useState(2);
  const [numTimepoints, setNumTimepoints] = useState(3); // Default to Week 24 (3 points: 4, 12, 24)
  const [treatmentEffect, setTreatmentEffect] = useState(0.4); // Spatial co-localization change
  const [patientVariance, setPatientVariance] = useState(0.6); // Inter-patient ICC
  const [sliceVariance, setSliceVariance] = useState(0.2); // Intra-patient slice ICC
  const [showCostLogic, setShowCostLogic] = useState(false);

  const currentPlatform = PLATFORMS[platform];
  const currentTimepointLabel = TIMEPOINTS_MAP.find(t => t.count === numTimepoints)?.label || 'Wk 24';

  // --- Logic (PoweREST inspired hierarchical power) ---
  const calculationResults = useMemo(() => {
    const alpha = 0.05;

    // Total Variance = Patient + Slice + Technical
    // Hierarchical variance decomposition: Var_total = sigma_p^2 + sigma_s^2 + sigma_t^2
    const sigmaP2 = Math.pow(patientVariance, 2);
    const sigmaS2 = Math.pow(sliceVariance, 2);
    const sigmaT2 = currentPlatform.technicalVariance / currentPlatform.captureEfficiency;

    // Longitudinal factor: more timepoints on the same patient reduce effective variance of the slope/endpoint
    // Simplified LMM approximation: precision increases with number of timepoints T
    const longitudinalGain = 1 + (numTimepoints - 1) * 0.45;

    const calculateForN = (N: number, S: number, T: number) => {
      // SE of the treatment effect estimate
      const se = Math.sqrt(
        (sigmaP2 / (N * longitudinalGain)) + 
        (sigmaS2 / (N * S * T)) + 
        (sigmaT2 / (N * S * T * 500))
      );

      const z = (treatmentEffect / se) - getZScore(1 - alpha/2);
      return Math.max(0, Math.min(1, getNormalProbability(z)));
    };

    const powerCurve = [];
    for (let n = 4; n <= 80; n += 4) {
      powerCurve.push({
        n,
        power: parseFloat((calculateForN(n, slicesPerPatient, numTimepoints) * 100).toFixed(1)),
        cost: parseFloat((n * slicesPerPatient * numTimepoints * currentPlatform.costPerSlice / 1000).toFixed(1))
      });
    }

    const currentPower = calculateForN(numPatients, slicesPerPatient, numTimepoints);

