        x, y, 
        type: isTumor ? (isInfiltrated ? 'Immune' : 'Tumor') : 'Stroma',
        color: isTumor ? (isInfiltrated ? '#10b981' : '#ef4444') : '#94a3b8'
      });
    }
    return dots;
  }, [treatmentEffect, numTimepoints]);

