  const [sliceVariance, setSliceVariance] = useState(0.2); 
  const [showCostLogic, setShowCostLogic] = useState(false);

  // --- Temporal Interactivity State ---
  const [visualTimepoint, setVisualTimepoint] = useState(3); // Tissue mockup timeline (1-4)
  const [analysisTimepoint, setAnalysisTimepoint] = useState(3); // Chart sensitivity interim (1-4)
