  };

  const handleDownloadCSV = (type: string) => {
    const headers = type === 'Frontier' ? ['N', 'Pilot_Power', 'RCT_Power'] : ['N', 'Pilot_Cost_k', 'RCT_Cost_k', 'Pilot_Power', 'RCT_Power'];
    const rows = calculationResults.dualCurve.map(d => {
